        metadata={},
    )


def artifact_to_operation_result(artifact: Any) -> OperationResult[dict[str, Any]]:
    trace = getattr(artifact, "trace", None)
    if isinstance(trace, dict):
        return OperationResult.success(
            trace,
            diagnostics={
                "run_id": getattr(artifact, "run_id", None),
                "augmenter_id": getattr(artifact, "augmenter_id", None),
                "engine_id": getattr(artifact, "engine_id", None),
                "status": getattr(artifact, "status", None),
            },
        )

    return OperationResult.failure(
        code="missing_trace",
        message="Run artifact does not contain a serialized trace.",
        details={
            "run_id": getattr(artifact, "run_id", None),
            "status": getattr(artifact, "status", None),
        },
    )

"""Read Thunderbird Gloda metadata and extensionless mbox files.

The v0 reader is fixture-first and read-only. It iterates mbox messages as the
source of truth, then enriches by matching bracket-stripped Message-ID headers to
Gloda ``messages.headerMessageID`` rows. It never seeks by ``messageKey``.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone
from email.message import Message
from email.utils import getaddresses, parsedate_to_datetime
import html
import json
import mailbox
from pathlib import Path
from urllib.parse import unquote, urlparse
import re
import sqlite3
from typing import Any, Iterable


ATTRIBUTE_FROM = 43
ATTRIBUTE_TO = 44
ATTRIBUTE_CC = 45
ATTRIBUTE_BCC = 46
ATTRIBUTE_INVOLVES = 52
ATTRIBUTE_RECIPIENTS = 53
ATTRIBUTE_FROM_ME = 54
ATTRIBUTE_TO_ME = 55
ATTRIBUTE_MAILING_LIST = 56
ATTRIBUTE_TAG = 57
ATTRIBUTE_STAR = 58
ATTRIBUTE_READ = 59
ATTRIBUTE_REPLIED_TO = 60
ATTRIBUTE_FORWARDED = 61


@dataclass(frozen=True)
class Identity:
    contact_id: int
    name: str
    address: str


@dataclass(frozen=True)
class MessageMetadata:
    header_message_id: str
    message_key: int | None
    folder_id: int | None
    conversation_id: int | None
    date: int | None
    sender_id: int | None
    recipient_ids: tuple[int, ...] = ()
    sender: Identity | None = None
    recipients: tuple[Identity, ...] = ()
    flags: dict[str, bool] = field(default_factory=dict)
    folder_uri: str | None = None
    folder_name: str | None = None


@dataclass(frozen=True)
class MailMessage:
    header_message_id: str
    subject: str
    body: str
    sender: str
    recipients: tuple[str, ...]
    date: str | None
    source_folder: str | None
    signal_folders: tuple[str, ...] = ()
    metadata: MessageMetadata | None = None
    mbox_path: Path | None = None
    local_read: bool = False
    read_state_source: str = "mbox"
    body_complete: bool = True
    body_is_bare_link: bool | None = None

    @property
    def has_gloda_metadata(self) -> bool:
        return self.metadata is not None


def normalize_message_id(value: str | None) -> str:
    """Normalize Message-ID values from mbox and Gloda for matching."""
    if not value:
        return ""
    return value.strip().strip("<>").strip()


def open_gloda_readonly(path: str | Path) -> sqlite3.Connection:
    """Open a Gloda fixture/database read-only with busy timeout."""
    db_path = Path(path)
    # Thunderbird may leave Gloda in exclusive locking mode even when it is not
    # running. Immutable mode bypasses those locks and guarantees this reader
    # cannot write to the profile; Gloda remains optional, lagging enrichment.
    conn = sqlite3.connect(f"file:{db_path}?mode=ro&immutable=1", uri=True)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA busy_timeout=3000")
    return conn


def _gloda_path(profile_root: Path) -> Path:
    fixture = profile_root / "gloda_fixture.sqlite"
    if fixture.exists():
        return fixture
    return profile_root / "global-messages-db.sqlite"


def load_attribute_definitions(conn: sqlite3.Connection) -> dict[int, str]:
    rows = conn.execute("SELECT id, name FROM attributeDefinitions").fetchall()
    return {int(row["id"]): str(row["name"]) for row in rows}


def _parse_json_attributes(raw: str | bytes | None) -> dict[int, Any]:
    if not raw:
        return {}
    if isinstance(raw, bytes):
        raw = raw.decode("utf-8")
    data = json.loads(raw)
    return {int(key): value for key, value in data.items()}


def _as_id_tuple(value: Any) -> tuple[int, ...]:
    if value is None:
        return ()
    if isinstance(value, list):
        return tuple(int(item) for item in value)
    return (int(value),)


def _as_bool(value: Any) -> bool:
    return bool(value) if isinstance(value, bool) else bool(value)


def _load_identities(conn: sqlite3.Connection) -> dict[int, Identity]:
    contacts = {
        int(row["id"]): str(row["name"] or "")
        for row in conn.execute("SELECT id, name FROM contacts")
    }
    identities: dict[int, Identity] = {}
    rows = conn.execute("SELECT contactID, kind, value FROM identities ORDER BY id").fetchall()
    for row in rows:
        contact_id = int(row["contactID"])
        kind = str(row["kind"] or "").lower()
        value = str(row["value"] or "")
        if contact_id in identities and kind != "email":
            continue
        identities[contact_id] = Identity(
            contact_id=contact_id,
            name=contacts.get(contact_id, ""),
            address=value,
        )
    return identities


def _load_folder_locations(conn: sqlite3.Connection) -> dict[int, tuple[str, str]]:
    rows = conn.execute("SELECT id, folderURI, name FROM folderLocations").fetchall()
    return {int(row["id"]): (str(row["folderURI"] or ""), str(row["name"] or "")) for row in rows}


def _cutoff_microseconds(newer_than: datetime | None) -> int | None:
    if newer_than is None:
        return None
    if newer_than.tzinfo is None:
        newer_than = newer_than.replace(tzinfo=timezone.utc)
    return int(newer_than.astimezone(timezone.utc).timestamp() * 1_000_000)


def load_gloda_metadata(
    profile_root: str | Path,
    *,
    newer_than: datetime | None = None,
) -> dict[str, MessageMetadata]:
    """Load Gloda metadata keyed by normalized header Message-ID."""
    db_path = _gloda_path(Path(profile_root))
    if not db_path.exists():
        return {}
    with open_gloda_readonly(db_path) as conn:
        identities = _load_identities(conn)
        folders = _load_folder_locations(conn)
        query = (
            "SELECT id, folderID, messageKey, conversationID, date, headerMessageID, "
            "deleted, jsonAttributes, notability FROM messages WHERE COALESCE(deleted, 0) = 0"
        )
        params: tuple[int, ...] = ()
        cutoff = _cutoff_microseconds(newer_than)
        if cutoff is not None:
            query += " AND date >= ?"
            params = (cutoff,)
        rows = conn.execute(query, params).fetchall()
        by_message_id: dict[str, MessageMetadata] = {}
        for row in rows:
            attrs = _parse_json_attributes(row["jsonAttributes"])
            sender_ids = _as_id_tuple(attrs.get(ATTRIBUTE_FROM))
            sender_id = sender_ids[0] if sender_ids else None
            recipient_ids = _as_id_tuple(attrs.get(ATTRIBUTE_TO)) + _as_id_tuple(
                attrs.get(ATTRIBUTE_RECIPIENTS)
            )
            recipient_ids = tuple(dict.fromkeys(recipient_ids))
            folder_id = int(row["folderID"]) if row["folderID"] is not None else None
            folder_uri, folder_name = folders.get(folder_id or -1, ("", ""))
            flags = {
                "from_me": _as_bool(attrs.get(ATTRIBUTE_FROM_ME, False)),
                "to_me": _as_bool(attrs.get(ATTRIBUTE_TO_ME, False)),
                "mailing_list": _as_bool(attrs.get(ATTRIBUTE_MAILING_LIST, False)),
                "star": _as_bool(attrs.get(ATTRIBUTE_STAR, False)),
                "read": _as_bool(attrs.get(ATTRIBUTE_READ, False)),
                "replied": _as_bool(attrs.get(ATTRIBUTE_REPLIED_TO, False)),
                "forwarded": _as_bool(attrs.get(ATTRIBUTE_FORWARDED, False)),
            }
            header_id = normalize_message_id(str(row["headerMessageID"] or ""))
            if not header_id:
                continue
            metadata = MessageMetadata(
                header_message_id=header_id,
                message_key=int(row["messageKey"]) if row["messageKey"] is not None else None,
                folder_id=folder_id,
                conversation_id=int(row["conversationID"])
                if row["conversationID"] is not None
                else None,
                date=int(row["date"]) if row["date"] is not None else None,
                sender_id=sender_id,
                recipient_ids=recipient_ids,
                sender=identities.get(sender_id) if sender_id is not None else None,
                recipients=tuple(identities[item] for item in recipient_ids if item in identities),
                flags=flags,
                folder_uri=folder_uri or None,
                folder_name=folder_name or None,
            )
            by_message_id[header_id] = metadata
        return by_message_id


def load_folder_tree(profile_root: str | Path) -> list[str]:
    path = Path(profile_root) / "folderTree.json"
    if not path.exists():
        return []
    data = json.loads(path.read_text(encoding="utf-8"))
    open_section = data.get("open", {})
    values = open_section.get("all", [])
    uris: list[str] = []
    for item in values:
        if isinstance(item, str):
            uris.append(item)
        elif isinstance(item, dict):
            uri = item.get("uri") or item.get("folderURI")
            if uri:
                uris.append(str(uri))
    return uris


def parse_folder_uri(uri: str) -> tuple[str, str, str]:
    parsed = urlparse(uri)
    account = unquote(parsed.username or "")
    host = parsed.hostname or ""
    folder_path = unquote(parsed.path.lstrip("/"))
    return account, host, folder_path


def discover_mbox_files(profile_root: str | Path) -> list[Path]:
    """Find extensionless Thunderbird mbox files marked by same-named .msf siblings."""
    root = Path(profile_root)
    mail_roots = [root / "ImapMail", root / "Mail"]
    found: list[Path] = []
    for mail_root in mail_roots:
        if not mail_root.exists():
            continue
        for path in mail_root.rglob("*"):
            if not path.is_file():
                continue
            if path.suffix == ".msf":
                continue
            if path.with_name(path.name + ".msf").exists():
                found.append(path)
    return sorted(found)


def _message_body(message: Message) -> str:
    if message.is_multipart():
        html_part = ""
        for part in message.walk():
            content_type = part.get_content_type()
            disposition = (part.get("Content-Disposition") or "").lower()
            if "attachment" in disposition:
                continue
            payload = _decode_part(part)
            if content_type == "text/plain" and payload.strip():
                return payload
            if content_type == "text/html" and payload.strip() and not html_part:
                html_part = _html_to_text(payload)
        return html_part
    if message.get_content_type() == "text/html":
        return _html_to_text(_decode_part(message))
    return _decode_part(message)


def load_message_body(mbox_path: str | Path, header_message_id: str) -> str:
    """Load one full message body from an mbox by normalized Message-ID."""
    target = normalize_message_id(header_message_id)
    if not target:
        raise ValueError("header_message_id is required")
    box = mailbox.mbox(Path(mbox_path), create=False)
    try:
        for message in box:
            if normalize_message_id(message.get("Message-ID")) == target:
                return _message_body(message)
    finally:
        box.close()
    raise KeyError(header_message_id)


def load_message_bodies(mbox_path: str | Path, header_message_ids: Iterable[str]) -> dict[str, str]:
    """Load full message bodies from one mbox by normalized Message-ID."""
    targets: dict[str, str] = {}
    for header_message_id in header_message_ids:
        target = normalize_message_id(header_message_id)
        if not target:
            raise ValueError("header_message_ids must not contain empty values")
        targets[target] = header_message_id
    if not targets:
        return {}

    found: dict[str, str] = {}
    box = mailbox.mbox(Path(mbox_path), create=False)
    try:
        for message in box:
            normalized = normalize_message_id(message.get("Message-ID"))
            original = targets.get(normalized)
            if original is None:
                continue
            found[original] = _message_body(message)
            if len(found) == len(targets):
                break
    finally:
        box.close()
    return found


def _decode_part(message: Message) -> str:
    payload = message.get_payload(decode=True)
    charset = message.get_content_charset() or "utf-8"
    if payload is None:
        text = message.get_payload()
        return text if isinstance(text, str) else ""
    return payload.decode(charset, errors="replace")


_TAG_RE = re.compile(r"<[^>]+>")
_HREF_RE = re.compile(r"""<a\b[^>]*\bhref\s*=\s*["']([^"']+)["'][^>]*>""", re.IGNORECASE)


def _html_to_text(text: str) -> str:
    """Convert HTML to visible text, preserving anchor href URLs.

    Tag stripping alone discards <a href="..."> targets, which silently loses
    URLs that are only present as link destinations (common in mail shared from
    a phone). Append each http(s) href so the URL survives in the body text.
    """
    hrefs = [
        unescaped
        for raw in _HREF_RE.findall(text)
        if (unescaped := html.unescape(raw)).lower().startswith(("http://", "https://"))
    ]
    stripped = html.unescape(_TAG_RE.sub(" ", text)).strip()
    if not hrefs:
        return stripped
    appended = " ".join(hrefs)
    return f"{stripped} {appended}".strip()


def _addresses(header_value: str | None) -> tuple[str, ...]:
    return tuple(address for _name, address in getaddresses([header_value or ""]) if address)


def _message_date(message: Message) -> str | None:
    parsed = _message_datetime(message)
    if parsed is not None:
        return parsed.isoformat()
    raw = message.get("Date")
    return str(raw) if raw else None


def _message_datetime(message: Message) -> datetime | None:
    raw = message.get("Date")
    if not raw:
        return None
    try:
        parsed = parsedate_to_datetime(raw)
    except Exception:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _mozilla_read(message: Message) -> bool:
    raw = str(message.get("X-Mozilla-Status") or "").strip()
    try:
        return bool(int(raw, 16) & 0x0001)
    except ValueError:
        return False


_MORK_ALIAS_RE = re.compile(r"\(([0-9A-F]+)\s*=([^)]*)\)", re.DOTALL)
_MORK_CELL_RE = re.compile(r"\(\^?([0-9A-F]+)(?:=([^)]*)|\^([0-9A-F]+))\)")
_MORK_ROW_RE = re.compile(r"\[-?[0-9A-F]+(?::(?:\^80|m))?(.*?)\]", re.DOTALL)
_MORK_MESSAGE_ID_FIELD = "83"
_MORK_FLAGS_FIELD = "88"
_THUNDERBIRD_READ_FLAG = 0x0001


def _decode_mork_value(value: str) -> str:
    return value.replace("\\\n", "").replace("\\)", ")").replace("\\\\", "\\")


def load_msf_read_states(msf_path: str | Path) -> dict[str, bool]:
    """Load Thunderbird .msf read flags keyed by normalized Message-ID.

    Thunderbird's Gloda database can lag behind the UI, and the mbox
    ``X-Mozilla-Status`` header can also be stale for IMAP folders. The sibling
    ``.msf`` summary is the source Thunderbird updates while displaying folder
    state. This intentionally parses only the small Mork subset needed for
    message rows: ``message-id`` and ``flags``.
    """
    path = Path(msf_path)
    if not path.exists():
        return {}
    text = path.read_text(errors="replace").replace("\\\n", "")
    aliases = {
        key.upper(): _decode_mork_value(value) for key, value in _MORK_ALIAS_RE.findall(text)
    }
    read_by_id: dict[str, bool] = {}
    for row in _MORK_ROW_RE.finditer(text):
        row_block = row.group(1)
        cells: dict[str, str] = {}
        for key, raw_value, alias_key in _MORK_CELL_RE.findall(row_block):
            key = key.upper()
            if alias_key:
                value = aliases.get(alias_key.upper(), alias_key)
            else:
                value = raw_value
            cells[key] = _decode_mork_value(value)
        message_id = normalize_message_id(cells.get(_MORK_MESSAGE_ID_FIELD))
        flags = cells.get(_MORK_FLAGS_FIELD)
        if not message_id or flags is None:
            continue
        try:
            read_by_id[message_id] = bool(int(flags, 16) & _THUNDERBIRD_READ_FLAG)
        except ValueError:
            continue
    return read_by_id


def _folder_label(path: Path) -> str:
    parts: list[str] = []
    current = path
    while current.parent.name.endswith(".sbd"):
        parts.append(current.name)
        current = current.parent.with_suffix("")
    parts.append(current.name)
    return "/".join(reversed(parts))


def _is_source_folder(label: str) -> bool:
    normalized = label.lower()
    return normalized.endswith("all mail") or normalized == "inbox"


def _message_from_mbox(
    message: Message,
    *,
    mbox_path: Path,
    folder_label: str,
    metadata: MessageMetadata | None,
    msf_read: bool | None = None,
) -> MailMessage | None:
    header_id = normalize_message_id(message.get("Message-ID"))
    if not header_id:
        return None
    sender = (
        metadata.sender.address
        if metadata and metadata.sender
        else (_addresses(message.get("From")) or ("",))[0]
    )
    recipients = (
        tuple(item.address for item in metadata.recipients)
        if metadata and metadata.recipients
        else _addresses(message.get("To"))
    )
    local_read = _mozilla_read(message) if msf_read is None else msf_read
    return MailMessage(
        header_message_id=header_id,
        subject=str(message.get("Subject") or ""),
        body=_message_body(message),
        sender=sender,
        recipients=recipients,
        date=_message_date(message),
        source_folder=folder_label if _is_source_folder(folder_label) else None,
        signal_folders=() if _is_source_folder(folder_label) else (folder_label,),
        metadata=metadata,
        mbox_path=mbox_path,
        local_read=local_read,
        read_state_source="mbox" if msf_read is None else "msf",
    )


def _merge_messages(existing: MailMessage, new: MailMessage) -> MailMessage:
    source_folder = existing.source_folder or new.source_folder
    signals = tuple(dict.fromkeys(existing.signal_folders + new.signal_folders))
    metadata = existing.metadata or new.metadata
    body_source = existing if existing.body else new
    if existing.read_state_source == "msf" and new.read_state_source == "msf":
        local_read = existing.local_read and new.local_read
        read_state_source = "msf"
    elif existing.read_state_source == "msf":
        local_read = existing.local_read
        read_state_source = "msf"
    elif new.read_state_source == "msf":
        local_read = new.local_read
        read_state_source = "msf"
    else:
        local_read = existing.local_read and new.local_read
        read_state_source = existing.read_state_source
    return MailMessage(
        header_message_id=existing.header_message_id,
        subject=body_source.subject,
        body=body_source.body,
        sender=existing.sender or new.sender,
        recipients=existing.recipients or new.recipients,
        date=existing.date or new.date,
        source_folder=source_folder,
        signal_folders=signals,
        metadata=metadata,
        mbox_path=body_source.mbox_path,
        local_read=local_read,
        read_state_source=read_state_source,
    )


def iter_messages(
    profile_root: str | Path,
    *,
    newer_than: datetime | None = None,
) -> Iterable[MailMessage]:
    """Yield deduplicated mbox messages enriched with Gloda metadata when present."""
    root = Path(profile_root)
    cutoff = newer_than
    if cutoff is not None and cutoff.tzinfo is None:
        cutoff = cutoff.replace(tzinfo=timezone.utc)
    if cutoff is not None:
        cutoff = cutoff.astimezone(timezone.utc)
    metadata_by_id = load_gloda_metadata(root, newer_than=cutoff)
    messages: dict[str, MailMessage] = {}
    for mbox_path in discover_mbox_files(root):
        folder_label = _folder_label(mbox_path)
        msf_read_by_id = load_msf_read_states(mbox_path.with_name(mbox_path.name + ".msf"))
        box = mailbox.mbox(mbox_path, create=False)
        try:
            for message in box:
                message_dt = _message_datetime(message)
                if cutoff is not None and (message_dt is None or message_dt < cutoff):
                    continue
                header_id = normalize_message_id(message.get("Message-ID"))
                if msf_read_by_id and header_id not in msf_read_by_id:
                    continue
                metadata = metadata_by_id.get(header_id)
                mail_message = _message_from_mbox(
                    message,
                    mbox_path=mbox_path,
                    folder_label=folder_label,
                    metadata=metadata,
                    msf_read=msf_read_by_id.get(header_id),
                )
                if mail_message is None:
                    continue
                if header_id in messages:
                    messages[header_id] = _merge_messages(messages[header_id], mail_message)
                else:
                    messages[header_id] = mail_message
        finally:
            box.close()
    return list(messages.values())

"""Detect repeated low-novelty tool actions without agent or engine coupling."""

from __future__ import annotations

from collections.abc import Iterable, Mapping, Sequence
from dataclasses import asdict, dataclass
import json
from pathlib import PurePosixPath
from typing import Any


_WARMUP_TOOL_ACTIONS = 8
_CONFIRMATION_ACTIONS = 2
_READ_OVERLAP_THRESHOLD = 0.50
_NOVELTY_THRESHOLD = 0.10
_TRAILING_COMPARISON_ACTIONS = 12
_REDIRECT_INSTRUCTION = (
    "The recent tool actions are repeating without adding evidence. Preserve the "
    "evidence already gathered and finalize the answer now."
)


@dataclass(frozen=True, slots=True)
class Intervention:
    """Advice returned after a confirmed action loop.

    ``truncation_point`` is a zero-based sequence offset. The caller retains
    trajectory entries before it and may discard entries from it onward.
    """

    truncation_point: int
    instruction: str
    loop_start_action: int
    confirmation_actions: int
    evidence_novelty: float
    repeated_action: str


@dataclass(frozen=True, slots=True)
class DetectorAssessment:
    """JSON-safe detector input and decision state for one trajectory check."""

    schema_version: int
    actions: tuple[dict[str, Any], ...]
    action_assessments: tuple[dict[str, Any], ...]
    intervention: Intervention | None

    def as_dict(self) -> dict[str, Any]:
        return {
            "schema_version": self.schema_version,
            "actions": [dict(action) for action in self.actions],
            "action_assessments": [dict(item) for item in self.action_assessments],
            "intervention": asdict(self.intervention) if self.intervention is not None else None,
        }


@dataclass(frozen=True, slots=True)
class _Action:
    sequence_offset: int
    action_number: int
    tool: str
    arguments: dict[str, Any]
    success: bool
    outcome_category: str | None
    evidence: frozenset[tuple[str, int | None]]


@dataclass(frozen=True, slots=True)
class _Assessment:
    action: _Action
    duplicate: bool
    novelty: float

    @property
    def redundant(self) -> bool:
        return self.duplicate and self.novelty <= _NOVELTY_THRESHOLD


def detect_and_redirect(
    action_trajectory: Sequence[object] | Iterable[object],
) -> Intervention | None:
    """Return redirect advice for a confirmed low-novelty action loop."""

    return assess_trajectory(action_trajectory).intervention


def assess_trajectory(
    action_trajectory: Sequence[object] | Iterable[object],
) -> DetectorAssessment:
    """Return the canonical detector input and every intermediate decision.

    The serialized ``actions`` can be passed back to this function directly.
    This makes live-versus-replay equivalence testable without reconstructing
    detector inputs from a more general run-record schema.
    """

    events = list(action_trajectory)
    actions = [
        action
        for offset, event in enumerate(events)
        if (action := _extract_action(event, offset)) is not None
    ]
    snapshots = tuple(_serialize_action(action) for action in actions)

    seen_evidence: set[tuple[str, int | None]] = set()
    assessments: list[_Assessment] = []
    serialized_assessments: list[dict[str, Any]] = []
    intervention = None
    for position, action in enumerate(actions):
        novelty = _novelty(action.evidence, seen_evidence)
        prior = actions[max(0, position - _TRAILING_COMPARISON_ACTIONS) : position]
        duplicate_actions = [
            candidate.action_number for candidate in prior if _near_duplicate(action, candidate)
        ]
        assessment = _Assessment(
            action=action,
            duplicate=bool(duplicate_actions),
            novelty=novelty,
        )
        assessments.append(assessment)
        serialized_assessments.append(
            {
                "action_number": action.action_number,
                "sequence_offset": action.sequence_offset,
                "comparison_window": [candidate.action_number for candidate in prior],
                "near_duplicate_actions": duplicate_actions,
                "evidence_atoms": len(action.evidence),
                "novel_evidence_atoms": len(action.evidence - seen_evidence),
                "novelty": novelty,
                "redundant": assessment.redundant,
            }
        )
        seen_evidence.update(action.evidence)

        # Both confirming actions must follow the completed warmup. With
        # zero-based positions, the second confirmer is warmup + 1.
        if position < _WARMUP_TOOL_ACTIONS + 1:
            continue
        if position == 0 or not assessment.redundant:
            continue
        previous = assessments[position - 1]
        confirmed_pair = previous.redundant or (
            previous.novelty <= _NOVELTY_THRESHOLD
            and _near_duplicate(assessment.action, previous.action)
        )
        if confirmed_pair and intervention is None:
            intervention = Intervention(
                truncation_point=previous.action.sequence_offset,
                instruction=_REDIRECT_INSTRUCTION,
                loop_start_action=previous.action.action_number,
                confirmation_actions=_CONFIRMATION_ACTIONS,
                evidence_novelty=max(previous.novelty, assessment.novelty),
                repeated_action=_signature(previous.action),
            )
    return DetectorAssessment(
        schema_version=2,
        actions=snapshots,
        action_assessments=tuple(serialized_assessments),
        intervention=intervention,
    )


def _extract_action(event: object, offset: int) -> _Action | None:
    action = _field(event, "action")
    if action is None or _field(action, "kind") != "tool":
        return None
    call = _field(action, "tool_call")
    if call is None:
        return None
    tool = _field(call, "name")
    arguments = _field(call, "arguments")
    if not isinstance(tool, str) or not isinstance(arguments, Mapping):
        raise TypeError(f"trajectory event {offset} has an invalid tool call")

    observation = _field(event, "observation")
    result = _field(observation, "tool_result") if observation is not None else None
    success = bool(_field(result, "success")) if result is not None else False
    result_meta = _field(result, "meta") if result is not None else None
    observation_meta = _field(observation, "meta") if observation is not None else None
    meta = result_meta if isinstance(result_meta, Mapping) else observation_meta
    typed_meta = meta if isinstance(meta, Mapping) else {}
    evidence = _evidence_atoms(typed_meta)
    category = typed_meta.get("category")
    number = _field(event, "index")
    action_number = int(number) if isinstance(number, int) else offset + 1
    captured_offset = _field(event, "_detector_sequence_offset")
    sequence_offset = int(captured_offset) if isinstance(captured_offset, int) else offset
    return _Action(
        sequence_offset=sequence_offset,
        action_number=action_number,
        tool=tool,
        arguments=dict(arguments),
        success=success,
        outcome_category=str(category) if category is not None else None,
        evidence=frozenset(evidence),
    )


def _serialize_action(action: _Action) -> dict[str, Any]:
    evidence = [
        {"path": path, "line": line}
        for path, line in sorted(
            action.evidence,
            key=lambda atom: (atom[0], -1 if atom[1] is None else atom[1]),
        )
    ]
    return {
        "_detector_sequence_offset": action.sequence_offset,
        "index": action.action_number,
        "action": {
            "kind": "tool",
            "tool_call": {"name": action.tool, "arguments": dict(action.arguments)},
        },
        "observation": {
            "tool_result": {
                "success": action.success,
                "meta": {
                    "category": action.outcome_category,
                    "evidence": [
                        {
                            "path": item["path"],
                            "lines": [] if item["line"] is None else [item["line"]],
                        }
                        for item in evidence
                    ],
                },
            }
        },
    }


def _field(value: object, name: str) -> object | None:
    if isinstance(value, Mapping):
        return value.get(name)
    return getattr(value, name, None)


def _canonical_path(value: object) -> str:
    text = str(value or ".").replace("\\", "/")
    normalized = PurePosixPath(text).as_posix()
    while normalized.startswith("./"):
        normalized = normalized[2:]
    return normalized or "."


def _evidence_atoms(meta: Mapping[str, object]) -> set[tuple[str, int | None]]:
    atoms: set[tuple[str, int | None]] = set()
    evidence = meta.get("evidence")
    if isinstance(evidence, list):
        for item in evidence:
            if not isinstance(item, Mapping) or "path" not in item:
                continue
            path = _canonical_path(item["path"])
            lines = item.get("lines")
            if isinstance(lines, list) and lines:
                atoms.update((path, int(line)) for line in lines if isinstance(line, int))
            else:
                atoms.add((path, None))
    paths = meta.get("paths")
    if isinstance(paths, list):
        atoms.update((_canonical_path(path), None) for path in paths if isinstance(path, str))
    return atoms


def _novelty(
    evidence: frozenset[tuple[str, int | None]],
    seen: set[tuple[str, int | None]],
) -> float:
    if not evidence:
        return 0.0
    novel = evidence - seen
    return len(novel) / len(evidence)


def _near_duplicate(current: _Action, prior: _Action) -> bool:
    if current.tool != prior.tool:
        return False
    if current.tool == "read_file":
        if _canonical_path(current.arguments.get("path")) != _canonical_path(
            prior.arguments.get("path")
        ):
            return False
        current_range = _read_range(current.arguments)
        prior_range = _read_range(prior.arguments)
        if current_range is None or prior_range is None:
            return _normalized_arguments(current.arguments) == _normalized_arguments(
                prior.arguments
            )
        overlap = max(
            0, min(current_range[1], prior_range[1]) - max(current_range[0], prior_range[0]) + 1
        )
        smaller = min(current_range[1] - current_range[0] + 1, prior_range[1] - prior_range[0] + 1)
        return overlap / smaller >= _READ_OVERLAP_THRESHOLD
    return _normalized_arguments(current.arguments) == _normalized_arguments(prior.arguments)


def _read_range(arguments: Mapping[str, Any]) -> tuple[int, int] | None:
    if arguments.get("full") is True:
        return None
    start = arguments.get("start_line", 1)
    count = arguments.get("line_count")
    if not isinstance(start, int) or not isinstance(count, int) or count < 1:
        return None
    return start, start + count - 1


def _normalized_arguments(arguments: Mapping[str, Any]) -> str:
    ignored = {"max_matches", "max_results", "line_count", "start_line"}
    normalized = {
        key: (_canonical_path(value) if key == "path" else value)
        for key, value in arguments.items()
        if key not in ignored
    }
    return json.dumps(normalized, sort_keys=True, separators=(",", ":"), default=str)


def _signature(action: _Action) -> str:
    return f"{action.tool} {_normalized_arguments(action.arguments)}"

    @property
    def has_gloda_metadata(self) -> bool:
        return self.metadata is not None


def normalize_message_id(value: str | None) -> str:
    """Normalize Message-ID values from mbox and Gloda for matching."""
    if not value:
        return ""
    return value.strip().strip("<>").strip()


def open_gloda_readonly(path: str | Path) -> sqlite3.Connection:
    """Open a Gloda fixture/database read-only with busy timeout."""
    db_path = Path(path)
    # Thunderbird may leave Gloda in exclusive locking mode even when it is not
    # running. Immutable mode bypasses those locks and guarantees this reader
    # cannot write to the profile; Gloda remains optional, lagging enrichment.
    conn = sqlite3.connect(f"file:{db_path}?mode=ro&immutable=1", uri=True)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA busy_timeout=3000")
    return conn


def _gloda_path(profile_root: Path) -> Path:
    fixture = profile_root / "gloda_fixture.sqlite"
    if fixture.exists():
        return fixture
    return profile_root / "global-messages-db.sqlite"

